'use client';import {useState} from 'react';import {Plus,Pencil} from 'lucide-react';import {money,today,Product} from '@/lib/data';import {useStore} from '@/lib/store';import {Panel,Toolbar} from '@/components/Panel';
export default function Stock(){const{products,setProducts,setStockLogs,role,toast}=useStore();const[p,setP]=useState<Product|null>(null);const[q,setQ]=useState('');const[e,setE]=useState('');function save(){if(!p||Number(q)<=0){toast('Enter stock quantity');return}const qty=Number(q),cost=Number(e)||p.expense;setProducts(v=>v.map(x=>x.id===p.id?{...x,stock:x.stock+qty,expense:role==='admin'?cost:x.expense}:x));setStockLogs(v=>[{id:Date.now(),productId:p.id,productName:p.name,qty,expense:cost,date:today(),type:'Purchase'},...v]);setP(null);setQ('');setE('');toast('Stock updated')}return <><Toolbar title="Stock Management" subtitle="Monitor stock quantity and add new purchases"/><Panel><div className="filterbar"><div className="search-box dark"><input value={q} onChange={x=>setQ(x.target.value)} placeholder="Search product..."/></div></div><div className="table-card"><table><thead><tr><th>Product</th><th>Category</th><th>Current Stock</th>{role==='admin'&&<th>Expense / Unit</th>}<th>Status</th><th>Action</th></tr></thead><tbody>{products.filter(x=>x.name.toLowerCase().includes(q.toLowerCase())).map(x=><tr key={x.id}><td><div className="prod-cell"><img src={x.image}/><b>{x.name}</b></div></td><td>{x.category}</td><td><b>{x.stock}</b></td>{role==='admin'&&<td>{money(x.expense)}</td>}<td><span className={x.stock<5?'pill low':'pill good'}>{x.stock<5?'Low Stock':'In Stock'}</span></td><td><button className="icon-btn" onClick={()=>setP(x)}><Plus size={16}/></button></td></tr>)}</tbody></table></div></Panel>{p&&<div className="overlay"><div className="modal"><button className="modal-x" onClick={()=>setP(null)}>×</button><h2>Add Stock</h2><p>{p.name} · Current {p.stock}</p><label>Quantity<input type="number" value={q} onChange={x=>setQ(x.target.value)}/></label>{role==='admin'&&<label>Purchase Expense / Unit<input type="number" value={e} onChange={x=>setE(x.target.value)} placeholder={String(p.expense)}/></label>}<div className="modal-actions"><button onClick={()=>setP(null)}>Cancel</button><button className="primary-btn" onClick={save}><Plus/> Add Stock</button></div></div></div>}</>}
